"""Build the two-stage Kaggle notebook from repo files.

python scripts/build_notebook.py
  -> notebooks/work03_local_llm.ipynb and kaggle/train/work03_train.ipynb (STAGE='train', identical)
python scripts/build_notebook.py --lock <downloaded train output>/work03/outputs/frozen.json [--accept-failed-gate REASON] [--accept-code-change REASON]
  -> also kaggle/eval/work03_eval.ipynb (STAGE='eval', reviewed lock sha256 embedded)
The train stage never mounts or reads holdout8. The eval notebook exists only after a lock is reviewed.
After the freeze only measurement/eval code (workflow.POST_FREEZE_CODE) may differ from the lock, declared with a reason;
in workflow.py every top-level statement outside POST_FREEZE_EXEMPT (prompt building, loading, decoding, repair) must stay identical."""
import argparse,ast,hashlib,json,time
from pathlib import Path
R=Path(__file__).resolve().parents[1]
FILES=['data/train12.csv','data/train_targets.jsonl','data/split-manifest.json','knowledge.json','system_prompt.txt','schema.json','run_config.json','evaluation_policy.json','scripts/workflow.py','scripts/audit_io.py','scripts/selfcheck.py','scripts/test_workflow.py']
CANONICAL=R/'notebooks/work03_local_llm.ipynb'
TRAIN_NB=R/'kaggle/train/work03_train.ipynb'
EVAL_NB=R/'kaggle/eval/work03_eval.ipynb'
PIP=['transformers==4.57.6','peft==0.20.0','accelerate==1.14.0','bitsandbytes==0.50.2','datasets==4.8.5','jsonschema>=4,<5','pandas>=2,<3']
# Default-deny: every top-level statement of workflow.py must match the frozen copy except these. Report code never
# generates; the eval glue (evaluate, holdout_run, evaluate_base) is exercised by verify_notebook.py with a recording fake
# model (load gets adapter=True then False; generate gets exactly (tok, model, msg)). In __main__ only the CLI choices may differ.
POST_FREEZE_EXEMPT={'__doc__','POST_FREEZE_CODE','check_freeze','report','report_html','audit_records','evaluate','holdout_run','evaluate_base'}
def payload():return {n:(R/n).read_text(encoding='utf-8-sig') for n in FILES}
def module_surface(src):
 """{key: [ast dumps]} per top-level statement; imports and other statements are keyed by their own source text."""
 class NoChoices(ast.NodeTransformer):
  def visit_keyword(self,k):return ast.keyword(arg=k.arg,value=ast.Constant(None)) if k.arg=='choices' else self.generic_visit(k)
 s={};body=ast.parse(src).body
 for i,n in enumerate(body):
  if i==0 and isinstance(n,ast.Expr) and isinstance(n.value,ast.Constant) and isinstance(n.value.value,str):k='__doc__'
  elif isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):k=n.name
  elif isinstance(n,ast.Assign):k=','.join(ast.unparse(t) for t in n.targets)
  elif isinstance(n,ast.If) and ast.unparse(n.test)=="__name__ == '__main__'":k='__main__';n=NoChoices().visit(n)
  else:k=ast.unparse(n)
  s.setdefault(k,[]).append(ast.dump(n))
 return s
def post_freeze_diff(frozen,local):
 """Top-level statements of workflow.py that differ from the frozen copy and are not exempt (empty = acceptable)."""
 a,b=module_surface(frozen),module_surface(local)
 return sorted(k for k in a.keys()|b.keys() if a.get(k)!=b.get(k) and k not in POST_FREEZE_EXEMPT)
def text_sha(s):return hashlib.sha256(s.encode('utf-8')).hexdigest()
def holdout_sha():return hashlib.sha256((R/'data/holdout8.csv').read_bytes()).hexdigest()

def cells(stage,lock_sha=None,decision=None):
 assert stage in ('train','eval') and (stage=='train')==(lock_sha is None)
 c=[]
 def add(kind,s):c.append(dict(cell_type=kind,id=f'c{len(c):02d}',metadata={},source=s,**({'execution_count':None,'outputs':[]} if kind=='code' else {})))
 add('markdown','# 任務三｜Local LLM SEO診斷（兩階段提交）\n以Qwen3-8B本地權重做4-bit LoRA微調與審核，無雲端推論API。同一份Notebook以`STAGE`分成兩個Kaggle提交版本：\n- `train`：部署、LoRA、三溫度一致性、train12自檢與候選鎖；不掛載、不讀取holdout。\n- `eval`：審閱train結果後才產生；先核對鎖的sha256及全部凍結檔，之後才讀私人holdout8；凍結的adapter與同prompt無adapter各跑一次8筆，輸出JSON、CSV、HTML及DataFrame。\n模型只用device0，T4 x2不當共享32GB。')
 if stage=='eval':
  ch=decision.get('code_changes') or {}
  add('markdown','## 本次凍結決定\n'+f"- 鎖：`{lock_sha}`，即train kernel輸出的frozen.json，未改寫。\n- 鎖內train gate：**{decision['gate_status']}**（{decision['hard_failures']}項hard，凍結時的檢查器）。"
   +('' if decision['gate_status']=='PASS' else f"**train gate未通過即凍結，依事前停損規則。** 理由：{decision['accepted_failed_gate_reason']}")
   +('' if not ch else f"\n- 凍結後只改量測與eval程式（已宣告，Kaggle上逐檔核對雜湊；生成路徑、prompt、知識卡、設定、契約與adapter不變）：{', '.join('`'+n+'`' for n in sorted(ch))}。理由：{decision['accepted_code_change_reason']}"))
 add('code',f"# Generated by scripts/build_notebook.py; do not edit on Kaggle.\nSTAGE={stage!r}\nEXPECTED_LOCK_SHA256={lock_sha!r}\nFREEZE_DECISION={decision!r}\nHOLDOUT_SHA256={holdout_sha()!r}")
 add('code',"import sys,os,json,subprocess,hashlib,shutil\nfrom pathlib import Path\nassert STAGE in ('train','eval'),STAGE\nROOT=Path('/kaggle/working/work03');INPUT=Path('/kaggle/input')\ndef find(name):\n # os.walk follows symlinked input mounts; Path.rglob in Python 3.13 does not.\n return sorted(Path(d)/name for d,_,fs in os.walk(INPUT,followlinks=True) if name in fs) if INPUT.exists() else []\ndef inputs():return sorted(str(p.relative_to(INPUT)) for p in INPUT.glob('*/*')) if INPUT.exists() else []\nif STAGE=='train':\n assert not find('holdout8.csv') and not find('seo-diagnostic-samples.csv'),'Train stage must not mount holdout8 or the full 20-row data'\nROOT.mkdir(parents=True,exist_ok=True)\npayload="+repr(payload())+"\nfor name,text in payload.items():\n p=ROOT/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8',newline='')\n(ROOT/'outputs').mkdir(exist_ok=True)\nprint(STAGE,'stage: train12, targets, knowledge, prompt and code written; holdout snippets not embedded')")
 add('code',f"subprocess.run([sys.executable,'-m','pip','install',*{PIP!r}],check=True)\ndef run(stage,check=True):\n # One T4 per subprocess: round-1 attempt 1 failed when Trainer used DataParallel on 4-bit weights.\n return subprocess.run([sys.executable,str(ROOT/'scripts/workflow.py'),stage],check=check,env={{**os.environ,'CUDA_VISIBLE_DEVICES':'0','PYTORCH_CUDA_ALLOC_CONF':'expandable_segments:True'}}).returncode\nrun('check-targets')\nsubprocess.run([sys.executable,str(ROOT/'scripts/test_workflow.py')],check=True)")
 add('markdown','## 部署與實際微調\n記錄硬體、固定Hub revision、套件版本、顯存及中文smoke，再用12筆監督答案做LoRA；只對答案tokens計算loss，禁止截斷。\n監督答案由AI協作研究撰寫，非公司官方gold、未經使用者獨立審閱。12筆易過度擬合，不以train loss宣稱泛化。3 epochs（約9 steps）、r8 q/v、batch1、累積4、1e-4；程式確認非零step及adapter權重實際改變。監督答案的鍵順序為Reasons（含severity）→Score→Actionable Advice，讓分數在證據與嚴重度之後才生成。\neval版本不重新訓練：載入train版本Output，核對鎖後使用同一adapter。')
 add('code',"def show(name):print(name);print((ROOT/'outputs'/name).read_text(encoding='utf-8'))\nif STAGE=='train':\n run('preflight');run('train')\nelse:\n locks=[p for p in find('frozen.json') if p.parent.name=='outputs' and p.parent.parent.name=='work03']\n assert len(locks)==1,f'Attach exactly one train-stage kernel output via kernel_sources; found {locks}; inputs {inputs()}'\n assert EXPECTED_LOCK_SHA256 and hashlib.sha256(locks[0].read_bytes()).hexdigest()==EXPECTED_LOCK_SHA256,'Mounted train bundle is not the reviewed lock'\n src=locks[0].parent\n for p in src.rglob('*'):\n  if p.is_file():\n   d=ROOT/'outputs'/p.relative_to(src);d.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,d)\n # The reviewed decision (incl. declared post-freeze code changes) is what check-freeze verifies against.\n (ROOT/'outputs/freeze_decision.json').write_text(json.dumps(dict(lock_sha256=EXPECTED_LOCK_SHA256,**FREEZE_DECISION),ensure_ascii=False,indent=2),encoding='utf-8')\n run('check-freeze')\nfor name in ['hardware.json','model.json','training.json']:show(name)")
 add('markdown','## 同文三次一致性與train12自檢\n一致性：預先指定train ID14，temperature 0.2/0.5/0.8各一次，seed42，不修復、不挑輸出；比較代碼Jaccard與分數極差，建議矛盾須語意審閱。此實驗同時含溫度與抽樣變因，不單獨推論溫度因果。\n自檢：12筆train使用與holdout相同的greedy解碼及最多一次修正；同一prompt不載入adapter再跑一次（baseline_comparison.json），用來說明LoRA實際增加了什麼。scripts/selfcheck.py在凍結前固定hard檢查：輸出契約有效（schema含severity、原文引句、來源ID、Score落在最高severity區間：critical 0–29、major 30–59、minor 60–84、無原因85–100；不一致只退回重試，程式不改分）、無虛構自述經驗、不建議刪除或淡化風險揭露、法條知識卡不跨主題、單一原因不貼4張以上來源、train標註中的錯誤SEO理論／堆疊／YMYL／自述經驗須被指出、ID14與7須在0–29分、ID20不得被標重大問題、明確無YMYL的train文章（ID5、10有爭議，不計）被標YMYL_RISK不得超過1篇。這是in-sample檢查，必要但不充分；語意仍逐項審閱。')
 add('code',"if STAGE=='train':\n run('consistency');run('selfcheck');run('baseline')\ng=json.loads((ROOT/'outputs/train_gate.json').read_text(encoding='utf-8'))\nprint('Train gate:',g['status'],'| self-check JSON first/final',g['selfcheck_first_pass_valid'],g['selfcheck_final_valid'],'| consistency valid',g['consistency_valid'])\nfor f in g['hard_failures']:print('HARD',f['where'],f['code'],f['detail'])\nimport pandas as pd\nfrom IPython.display import display\ndisplay(pd.DataFrame(g['items']));display(pd.DataFrame(g['consistency_runs']))\nprint(json.dumps(json.loads((ROOT/'outputs/consistency.json').read_text(encoding='utf-8'))['summary'],ensure_ascii=False,indent=1))\nb=json.loads((ROOT/'outputs/baseline_comparison.json').read_text(encoding='utf-8'))\nprint('train12 hard failures, same prompt with vs without adapter:',b['hard_counts'],'| first-pass valid',b['first_pass_valid'])\ndisplay(pd.DataFrame(b['items']))")
 add('code',"lock_path=ROOT/'outputs/frozen.json'\nif STAGE=='train':\n run('freeze')\n print('Candidate lock sha256:',hashlib.sha256(lock_path.read_bytes()).hexdigest())\n print('Train stage complete; holdout8 was not mounted or read. Review train_gate.json, then build the eval notebook with this lock.')\nelse:\n print('Frozen lock accepted:',EXPECTED_LOCK_SHA256);print(json.dumps(FREEZE_DECISION,ensure_ascii=False,indent=1))")
 add('markdown','## 凍結與獨立8筆批次審核\n只有eval版本執行。審閱train自檢後，以build_notebook.py --lock嵌入候選鎖sha256；Kaggle上先核對鎖與模型設定、prompt、知識卡、程式、adapter及train證據的hash，之後才定位私人holdout8.csv、核對原bytes雜湊並複製。Notebook未嵌入8筆文章。\n每筆最多一次修正（JSON結構、引句、來源或Score與severity區間不一致時，把錯誤回饋給模型重寫；程式不改分），原始輸出、修正輸出與失敗都保留；首次與修正後契約有效率分列。AutoFlags是讀holdout前固定的啟發式檢查（凍結後的checker修正見本次凍結決定），不是準確率。\n同一prompt、解碼與修正規則再以不載入adapter的base模型跑同8筆（holdout_base.jsonl、audit_report_base.csv、holdout_comparison.csv），只作比較，說明LoRA在未見資料上的實際增量；base失敗不影響adapter結果。三溫度一致性已在train版本完成，eval不重跑。')
 add('code',"if STAGE=='eval':\n holdouts=find('holdout8.csv')\n assert len(holdouts)==1,f'Attach exactly one private holdout8.csv dataset; found {holdouts}; inputs {inputs()}'\n assert hashlib.sha256(holdouts[0].read_bytes()).hexdigest()==HOLDOUT_SHA256,'holdout8.csv bytes changed'\n shutil.copyfile(holdouts[0],ROOT/'data/holdout8.csv')\n run('evaluate')\n if run('evaluate-base',check=False):print('WARNING: base (no adapter) comparison failed; adapter results are unaffected')\n run('report')\n df=pd.read_csv(ROOT/'outputs/audit_report.csv',encoding='utf-8-sig')\n display(df[['ID','Category','Score','MaxSeverity','Codes','AutoFlags','FirstPassValid','FinalValid']]);display(df)\n cmp=ROOT/'outputs/holdout_comparison.csv'\n if cmp.exists():display(pd.read_csv(cmp,encoding='utf-8-sig'))\n print((ROOT/'outputs/metrics.json').read_text(encoding='utf-8'))\nelse:\n print('Skipped in train stage: holdout8 is not mounted or read.')")
 add('markdown','## 逐筆說明與中文反思（實跑後填寫）\noutputs/manual_review.csv逐筆填寫：主要問題、漏判、誤判、來源支持0–2、建議可執行性0–2、為何準確或偏差及依據URL。事後AI評語不能當獨立人工gold或無偏準確率。\n中文反思依真實輸出回答：繁體用語是否自然？是否混淆台灣法域？是否把未驗證經驗當造假？是否被錯誤SEO理論帶偏？來源引用能否支持原因？prompt改善後哪些問題仍存在？各附成功及失敗原句，不預寫模型能力。\n保留train與eval兩個已執行版本及全部Output。未實跑前不得把本Notebook當完成成果。')
 return c

def notebook(cs):return dict(cells=cs,metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python'}},nbformat=4,nbformat_minor=5)
def dump(nb):return json.dumps(nb,ensure_ascii=False,indent=1)+'\n'
def save(path,nb):path.parent.mkdir(parents=True,exist_ok=True);path.write_text(dump(nb),encoding='utf-8',newline='')

def review_lock(lock_path,accept_failed_gate=None,accept_code_change=None):
 """Return (lock sha256, decision) only if the downloaded train lock matches local files and its gate."""
 lock_path=Path(lock_path);lock=json.loads(lock_path.read_text(encoding='utf-8'))
 from workflow import FROZEN_OUTPUTS,ADAPTER_REQUIRED,POST_FREEZE_CODE
 bundle=lock_path.parent.parent;local=payload()
 drift=[n for n,t in local.items() if lock['hashes'].get(n)!=text_sha(t)]
 blocked=[n for n in drift if n not in POST_FREEZE_CODE]
 assert not blocked,f'Local files differ from the frozen train bundle: {blocked}'
 if drift:assert accept_code_change,f'Post-freeze code changes {drift}; review, then pass --accept-code-change REASON'
 if 'scripts/workflow.py' in drift:
  fw=bundle/'scripts/workflow.py'
  assert fw.is_file() and hashlib.sha256(fw.read_bytes()).hexdigest()==lock['hashes']['scripts/workflow.py'],'Bundle workflow.py missing or not the frozen one'
  changed=post_freeze_diff(fw.read_text(encoding='utf-8'),local['scripts/workflow.py'])
  assert not changed,f'workflow.py changed outside the exempt measurement/eval code after freeze: {changed}'
 code_changes={n:dict(frozen_sha256=lock['hashes'][n],eval_sha256=text_sha(local[n])) for n in drift}
 # The reviewed downloads (gate, self-check, consistency, adapter) must be exactly what the lock covers.
 absent=[n for n in FROZEN_OUTPUTS+ADAPTER_REQUIRED if 'outputs/'+n not in lock['hashes']]
 assert not absent,f'Lock does not cover required train outputs: {absent}'
 changed=[n for n,d in lock['hashes'].items() if n.startswith('outputs/') and not ((bundle/n).is_file() and hashlib.sha256((bundle/n).read_bytes()).hexdigest()==d)]
 assert not changed,f'Downloaded train outputs differ from the lock: {changed}'
 g=json.loads((lock_path.parent/'train_gate.json').read_text(encoding='utf-8'))
 if g['status']!='PASS':
  assert accept_failed_gate,f"Train gate {g['status']} with {len(g['hard_failures'])} hard failures; review, then pass --accept-failed-gate REASON"
 decision=dict(gate_status=g['status'],hard_failures=len(g['hard_failures']),accepted_failed_gate_reason=accept_failed_gate,code_changes=code_changes,accepted_code_change_reason=accept_code_change if code_changes else None,lock_created_utc=lock.get('created_utc'),eval_built_utc=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()))
 return hashlib.sha256(lock_path.read_bytes()).hexdigest(),decision

if __name__=='__main__':
 ap=argparse.ArgumentParser(description=__doc__,formatter_class=argparse.RawDescriptionHelpFormatter)
 ap.add_argument('--lock',help='Reviewed train-stage work03/outputs/frozen.json downloaded with kaggle kernels output')
 ap.add_argument('--accept-failed-gate',default=None,help='Reason recorded when freezing despite hard gate failures')
 ap.add_argument('--accept-code-change',default=None,help='Reason recorded when measurement/eval code changed after the freeze (generation path must be unchanged)')
 a=ap.parse_args()
 nb=notebook(cells('train'));save(CANONICAL,nb);save(TRAIN_NB,nb)
 print('Built train-stage notebook (canonical and kaggle/train); no model results embedded')
 if a.lock:
  lock_sha,decision=review_lock(a.lock,a.accept_failed_gate,a.accept_code_change);save(EVAL_NB,notebook(cells('eval',lock_sha,decision)))
  print('Built kaggle/eval notebook for lock',lock_sha,decision)
